package com.inventra.backend.controller; import com.inventra.backend.dto.*; import com.inventra.backend.service.InventoryAssistantService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/assistant") public class AssistantController {private final InventoryAssistantService s;public AssistantController(InventoryAssistantService s){this.s=s;}@PostMapping("/ask") public AssistantResponse ask(@Valid @RequestBody AssistantRequest r){return s.ask(r.question());}}
